"""
DCC TCP 服务端启动脚本

此脚本可在任意 DCC 软件（Maya、3ds Max、Substance Painter 等）中运行，
启动 TCP 服务端以接收 VS Code 发送的 Python 代码执行请求。

使用方法：
1. Maya：在脚本编辑器（Python 标签）中运行此脚本
2. 3ds Max：拖拽此脚本到视图，或在脚本监听器中运行
3. Substance Painter：在 Python 控制台中运行此脚本
4. 其他 DCC：在任意 Python 环境中运行此脚本

默认端口：7002
如需更改端口，修改下方的 DEFAULT_PORT 常量，或在调用 start_server() 时传入参数
"""

import sys
import os

DEFAULT_PORT = 7002


def get_script_dir() -> str:
    """获取当前脚本所在目录"""
    try:
        return os.path.dirname(os.path.abspath(__file__))
    except:
        return os.path.dirname(sys.executable)


def add_site_packages_to_path() -> None:
    """将 site-packages 目录添加到 sys.path
    脚本在 vscode_dcc/ 目录中，父目录才是 site-packages
    """
    script_dir = get_script_dir()
    site_packages_dir = os.path.dirname(script_dir)
    print(f"Adding site-packages to sys.path: {site_packages_dir}")
    if site_packages_dir not in sys.path:
        sys.path.insert(0, site_packages_dir)
        print(f"Added to sys.path: {site_packages_dir}")


def detect_dcc() -> str:
    """自动检测当前运行的 DCC 软件
    
    Returns:
        DCC 名称：'maya', '3dsmax', 'substance_painter', 或 'generic'
    """
    # 检测 Maya
    try:
        import maya.cmds
        return 'maya'
    except ImportError:
        pass
    
    # 检测 3ds Max
    try:
        import pymxs
        return '3dsmax'
    except ImportError:
        pass
    
    # 检测 Substance Painter
    try:
        import substance_painter
        return 'substance_painter'
    except ImportError:
        pass
    
    # 未检测到特定 DCC，使用通用适配器
    return 'generic'


def get_adapter(dcc_name: str):
    """根据 DCC 名称获取对应的 Adapter
    
    Args:
        dcc_name: DCC 名称
        
    Returns:
        DCCAdapter 实例
    """
    from vscode_dcc.adapters.base import DCCAdapter, Logger
    
    if dcc_name == 'maya':
        try:
            from vscode_dcc.adapters.maya import MayaAdapter
            return MayaAdapter()
        except ImportError:
            print("MayaAdapter not available, using generic adapter")
            return DCCAdapter()
    
    elif dcc_name == '3dsmax':
        try:
            from vscode_dcc.adapters.max import MaxAdapter
            return MaxAdapter()
        except ImportError:
            print("MaxAdapter not available, using generic adapter")
            return DCCAdapter()
    
    elif dcc_name == 'substance_painter':
        try:
            from vscode_dcc.adapters.painter import SubstancePainterAdapter
            return SubstancePainterAdapter()
        except ImportError:
            print("SubstancePainterAdapter not available, using generic adapter")
            return DCCAdapter()
    
    else:
        # 通用适配器
        return DCCAdapter()


def start_server(port: int = DEFAULT_PORT):
    """启动 VS Code DCC TCP 服务端
    
    Args:
        port: 监听端口，默认 7002
        
    Returns:
        SocketServiceToggleTool 实例
    """
    add_site_packages_to_path()
    
    # 自动检测 DCC 环境
    dcc_name = detect_dcc()
    print(f"Detected DCC: {dcc_name}")
    
    try:
        from vscode_dcc.server import SocketServiceToggleTool
        
        adapter = get_adapter(dcc_name)
        adapter.name = dcc_name
        
        tool = SocketServiceToggleTool(adapter, port=port)
        tool.start()
        
        logger = adapter.get_logger()
        logger.info(f"VS Code DCC Server started on port {port}")
        print(f"VS Code DCC Server started on port {port}")
        print(f"Waiting for VS Code connections...")
        
        return tool
        
    except ImportError as e:
        print(f"Import error: {e}")
        print("Make sure the vscode_dcc package is in sys.path")
        raise
    except Exception as e:
        print(f"Error starting server: {e}")
        import traceback
        traceback.print_exc()
        raise


if __name__ == "__main__":
    start_server(DEFAULT_PORT)